const mcpToolResultMaxItems = 50

func mcpBoundedSingleArrayObject(data json.RawMessage) ([]byte, bool) {
	var obj map[string]json.RawMessage
	if json.Unmarshal(data, &obj) != nil {
		return nil, false
	}
	arrayField := ""
	var items []json.RawMessage
	for key, raw := range obj {
		trimmed := strings.TrimSpace(string(raw))
		if len(trimmed) == 0 || trimmed[0] != '[' {
			continue
		}
		var candidate []json.RawMessage
		if json.Unmarshal(raw, &candidate) != nil {
			continue
		}
		if arrayField != "" {
			return nil, false
		}
		arrayField = key
		items = candidate
	}
	if arrayField == "" {
		return nil, false
	}
	out := envelope.ObjectArray(obj, arrayField, items, envelope.Options{
		Count:          len(items),
		ItemCap:        mcpToolResultMaxItems,
		Note:           "Typed MCP endpoint response exceeded the tool result budget. Narrow the request with limit, offset, filters, search/sql, or a command-mirror tool with --agent/--compact/--select.",
		SupportsCursor: false,
	})
	if len(out) > envelope.MaxBytes() {
		return nil, false
	}
	return out, true
}

func mcpBoundedListEnvelope(items []json.RawMessage) []byte {
	return envelope.List(items, envelope.Options{
		Count:          len(items),
		ItemCap:        mcpToolResultMaxItems,
		SupportsCursor: false,
	})
}

func mcpOversizedPreviewEnvelope(data json.RawMessage) []byte {
	return envelope.Preview(data, envelope.MaxBytes(), "Typed MCP endpoint response exceeded the tool result budget and was not a recognized list envelope. Narrow the request with filters, search/sql, or a command-mirror tool with --agent/--compact/--select.")
}

var dbPath = func() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".local", "share", "readwise-pp-cli", "data.db")
}

// validateReadOnlyQuery gates the MCP sql tool. The agent contract advertised
// to the host is ReadOnlyHintAnnotation(true); a false annotation on a
// mutating tool lets MCP hosts auto-approve writes and is treated as a real
// bug per the project's agent-native security model.
//
// The gate rejects multi-statement input, then applies an allowlist (SELECT or
// WITH only) AFTER stripping the leading whitespace, line comments, block
// comments, and semicolons that SQLite itself ignores before parsing. A naive
// HasPrefix check on a keyword blocklist is bypassable by prefixing the
// dangerous statement with "/* x */" or "-- x\n"; a naive leading-keyword
// allowlist is bypassable by appending "; ATTACH DATABASE ...". Combined with
// the empirical fact that modernc.org/sqlite's mode=ro does NOT block VACUUM
// INTO (writes a snapshot to a new file) or ATTACH DATABASE (opens a separate
// writable handle), either bypass produces silent exfiltration to an
// attacker-chosen path.
//
// SELECT and WITH are the only allowed leading keywords. WITH supports
// SELECT-form CTEs; CTE-wrapped writes ("WITH x AS (...) INSERT ...") are
// caught by OpenReadOnly's mode=ro one layer down. PRAGMA, ATTACH, VACUUM,
// and every other DDL/DML keyword fail at this gate before reaching SQLite.
// sqlTableBlocklist lists table and internal-schema names that the MCP sql
// tool must never allow agents to query. Applied after the allowlist so
// SELECT-form queries that reference these tables are still rejected.
// All comparisons are case-insensitive against the upper-cased full query.
var sqlTableBlocklist = []string{
	"WEBHOOK",
	"WATCH_SAVED_SEARCH",
	"WATCH_SEEN",
	"PRAGMA_TABLE_LIST",
	"SQLITE_MASTER",
	"SQLITE_SCHEMA",
	"SQLITE_TEMP_",
	"DBSTAT",
	"SQLITE_STAT",
}

// boundedResultJSON renders a result SLICE as a byte-budgeted MCP text result,
// ALWAYS via the shared envelope so search/sql match the typed list tools'
// predictable shape regardless of size. itemCap<=0 = bound by bytes only.
// A non-array v falls back to toolResultJSON(v).
func boundedResultJSON(v any, itemCap int, note string) (*mcplib.CallToolResult, error) {
	return boundedResultJSONWithCount(v, itemCap, note, -1, 0, false)
}

func boundedResultJSONWithCount(v any, itemCap int, note string, totalCount int, offset int, supportsCursor bool) (*mcplib.CallToolResult, error) {
	data, err := json.Marshal(v)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding result: %v", err)), nil
	}
	var items []json.RawMessage
	if json.Unmarshal(data, &items) != nil {
		var obj map[string]json.RawMessage
		if json.Unmarshal(data, &obj) == nil && obj["rows"] != nil {
			if err := json.Unmarshal(obj["rows"], &items); err != nil {
				return toolResultJSON(v)
			}
			delete(obj, "rows")
			count := len(items)
			_ = json.Unmarshal(obj["count"], &count)
			nativeTruncated := false
			_ = json.Unmarshal(obj["truncated"], &nativeTruncated)
			raw := envelope.ObjectArray(obj, "results", items, envelope.Options{Count: count, Note: note})
			if nativeTruncated {
				var bounded map[string]json.RawMessage
				_ = json.Unmarshal(raw, &bounded)
				bounded["truncated"] = json.RawMessage("true")
				raw, _ = json.Marshal(bounded)
			}
			return mcplib.NewToolResultText(string(raw)), nil
		}
		return toolResultJSON(v)
	}
	if items == nil {
		items = []json.RawMessage{}
	}
	if totalCount < 0 {
		totalCount = len(items)
	}
	return mcplib.NewToolResultText(string(envelope.List(items, envelope.Options{
		Count:          totalCount,
		Offset:         offset,
		ItemCap:        itemCap,
		Note:           note,
		SupportsCursor: supportsCursor,
	}))), nil
}

func handleWatchList(ctx context.Context, _ mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	db, err := store.OpenReadOnly(dbPath())
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("opening database: %v", err)), nil
	}
	defer db.Close()
	watches, err := db.ListWatches(ctx)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("list watches: %v", err)), nil
	}
	return toolResultJSON(watches)
}

func handleWatchDiff(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	args := req.GetArguments()
	watchRef, ok := args["watch"].(string)
	if !ok || watchRef == "" {
		return mcplib.NewToolResultError("watch (name or id) is required"), nil
	}
	db, err := store.OpenReadOnly(dbPath())
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("opening database: %v", err)), nil
	}
	defer db.Close()
	w, err := db.GetWatch(ctx, watchRef)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("watch not found: %v", err)), nil
	}
	result, err := cli.WatchDiff(ctx, db, w)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("watch diff: %v", err)), nil
	}

	type diffItem struct {
		ID    string `json:"id"`
		Title string `json:"title"`
		URL   string `json:"url"`
	}
	var items []diffItem
	switch result.Kind {
	case "docs":
		for _, d := range result.DocItems {
			items = append(items, diffItem{ID: d.ID, Title: d.Title, URL: d.URL})
		}
	case "highlights":
		for _, h := range result.HLItems {
			items = append(items, diffItem{ID: h.ID, Title: h.Title, URL: h.URL})
		}
	}
	if items == nil {
		items = []diffItem{}
	}

	out := map[string]any{
		"watch":                w.Name,
		"kind":                 w.Kind,
		"new_count":            result.NewCount,
		"store_last_synced_at": result.LastSyncedAt,
		"items":                items,
	}
	data, err := json.Marshal(out)
	if err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding result: %v", err)), nil
	}
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(data, &obj); err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding result: %v", err)), nil
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(obj["items"], &rawItems); err != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("encoding result items: %v", err)), nil
	}
	return mcplib.NewToolResultText(string(envelope.ObjectArray(obj, "items", rawItems, envelope.Options{
		Count:          len(rawItems),
		ItemCap:        mcpToolResultMaxItems,
		Note:           "Watch diff response exceeded the tool result budget. Narrow the watch query or inspect matching items with search/sql.",
		SupportsCursor: false,
	}))), nil
}

func withSearchMetadata(result *mcplib.CallToolResult, metadata map[string]any, offset int) *mcplib.CallToolResult {
	if result == nil || len(result.Content) == 0 {
		return result
	}
	text, ok := result.Content[0].(mcplib.TextContent)
	if !ok {
		return result
	}
	var obj map[string]json.RawMessage
	if json.Unmarshal([]byte(text.Text), &obj) != nil {
		return result
	}
	for key, value := range metadata {
		if key == "results" || key == "count" {
			continue
		}
		raw, _ := json.Marshal(value)
		obj[key] = raw
	}
	var items []json.RawMessage
	_ = json.Unmarshal(obj["results"], &items)
	count := len(items)
	_ = json.Unmarshal(obj["count"], &count)
	obj["resumable"], _ = json.Marshal(count > offset+len(items))
	return mcplib.NewToolResultText(string(envelope.ObjectArray(obj, "results", items, envelope.Options{Count: count, Offset: offset, SupportsCursor: true, ItemCap: mcpToolResultMaxItems})))
}

// boundedSearchPage keeps search's item cap and offset contract shared with
// the canonical renderer before store-status metadata is attached.
func boundedSearchPage(results []json.RawMessage, totalCount, offset int) (*mcplib.CallToolResult, error) {
	return boundedResultJSONWithCount(results, mcpToolResultMaxItems, "", totalCount, offset, true)
}
